   152	void Leader::HandleServerData(Coap::Message &aMessage, const Ip6::MessageInfo &aMessageInfo)
   153	{
   154	    ThreadNetworkDataTlv networkData;
   155	    ThreadRloc16Tlv      rloc16;
   156	
   157	    otLogInfoNetData("Received network data registration");
   158	
   159	    if (ThreadTlv::GetTlv(aMessage, ThreadTlv::kRloc16, sizeof(rloc16), rloc16) == OT_ERROR_NONE)
   160	    {
   161	        VerifyOrExit(rloc16.IsValid());
   162	        RemoveBorderRouter(rloc16.GetRloc16(), kMatchModeRloc16);
   163	    }
   164	
   165	    if (ThreadTlv::GetTlv(aMessage, ThreadTlv::kThreadNetworkData, sizeof(networkData), networkData) == OT_ERROR_NONE)
   166	    {
   167	        VerifyOrExit(networkData.IsValid());
   168	        RegisterNetworkData(HostSwap16(aMessageInfo.mPeerAddr.mFields.m16[7]), networkData.GetTlvs(),
   169	                            networkData.GetLength());
   170	    }
   171	
   172	    SuccessOrExit(Get<Coap::Coap>().SendEmptyAck(aMessage, aMessageInfo));
   173	
   174	    otLogInfoNetData("Sent network data registration acknowledgment");
   175	
   176	exit:
   177	    return;
   178	}
