   291	void Leader::HandleCommissioningGet(Coap::Message &aMessage, const Ip6::MessageInfo &aMessageInfo)
   292	{
   293	    MeshCoP::Tlv tlv;
   294	    uint16_t     offset = aMessage.GetOffset();
   295	    uint8_t      tlvs[NetworkData::kMaxSize];
   296	    uint8_t      length = 0;
   297	
   298	    while (offset < aMessage.GetLength())
   299	    {
   300	        aMessage.Read(offset, sizeof(tlv), &tlv);
   301	
   302	        if (tlv.GetType() == MeshCoP::Tlv::kGet)
   303	        {
   304	            length = tlv.GetLength();
   305	            aMessage.Read(offset + sizeof(MeshCoP::Tlv), length, tlvs);
   306	            break;
   307	        }
   308	
   309	        offset += sizeof(tlv) + tlv.GetLength();
   310	    }
   311	
   312	    SendCommissioningGetResponse(aMessage, aMessageInfo, tlvs, length);
   313	}
